await page.waitForTimeout(120);const facts=await page.evaluate(()=>({title:document.title,canonical:document.querySelector('link[rel=canonical]')?.href,overflow:document.documentElement.scrollWidth-innerWidth,header:document.querySelector('.site-header')?.getBoundingClientRect().height,cssHeader:getComputedStyle(document.documentElement).getPropertyValue('--header'),ids:[...document.querySelectorAll('[id]')].map(e=>e.id),imageAlts:[...document.images].map(e=>e.alt),images:[...document.images].map(e=>({src:e.currentSrc,complete:e.complete,width:e.naturalWidth})),hintCount:[...document.querySelectorAll('.table-keyboard-hint')].filter(e=>!e.hidden).length}));assert.equal(facts.canonical,origin+route);assert(facts.overflow<=0,route+' overflow '+width+': '+facts.overflow);assert.equal(facts.ids.length,new Set(facts.ids).size);
