if(route.includes('/resources/')){assert.equal(await page.locator('h1').count(),1);assert((await page.locator('.resource-cards a').count())>20);}
if(route==='/'||['/es/','/ca/','/fr/'].includes(route)){const photo=page.locator('.founder-photo');await photo.scrollIntoViewIfNeeded();await page.waitForFunction(()=>{const e=document.querySelector('.founder-photo');return e.complete&&e.naturalWidth>0});const image=await photo.evaluate(e=>({currentSrc:e.currentSrc,naturalWidth:e.naturalWidth,alt:e.alt}));assert(image.currentSrc.includes('/assets/optimized/noah_levy_profile_picture-'));assert(/-(240|480)\.webp$/.test(image.currentSrc));facts.loadedFounder=image;if(width===390)await page.screenshot({path:path.join(out,(live?'live-':'preview-')+route.replaceAll('/','').replace(/^$/,'en')+'-home-founder.png'),timeout:30000}).catch(e=>{facts.screenshotWarning=e.message.slice(0,160)});}
